import { watch } from 'node:fs';
import { join } from 'node:path';

const SETTLE_MS = 300;
const IGNORED_DIRECTORIES = new Set([
    'target',
    'generated',
    'gen',
    'autogenerated',
    'node_modules',
]);

// Filter watcher events before scheduling a rebuild so Cargo and Tauri output cannot retrigger it
function watchedSource(scope, filename) {
    if (!filename) return false;
    if (!scope) return filename === 'Cargo.toml' || filename === 'Cargo.lock';
    const parts = filename.split(/[\\/]/);
    const name = parts.pop();
    if (parts.some((part) => IGNORED_DIRECTORIES.has(part))) return false;
    if (name.endsWith('.rs') || name === 'Cargo.toml') return true;
    if (scope === 'src-tauri' && ['capabilities', 'permissions'].includes(parts[0]))
        return /\.(json|toml)$/.test(name);
    return (
        scope === 'src-tauri' &&
        parts.length === 0 &&
        (name === 'Info.plist' || /^tauri(?:\.[\w-]+)?\.conf\.json$/.test(name))
    );
}

// Watch native source edits and return an idempotent disposer for all handles and pending changes
export function watchNativeSources(root, onChange, onError) {
    const watchers = [];
    let timer;
    let closed = false;

    // Stop accepting events before closing handles so queued events cannot schedule another rebuild
    function close() {
        if (closed) return;
        closed = true;
        clearTimeout(timer);
        for (const watcher of watchers) watcher.close();
    }

    // A failed watcher cannot promise complete coverage, so report it and dispose the rest
    function fail(error) {
        if (closed) return;
        close();
        onError(error);
    }

    try {
        for (const scope of ['', 'crates', 'src-tauri']) {
            const watcher = watch(
                join(root, scope),
                { recursive: Boolean(scope) },
                (_event, filename) => {
                    if (closed || !watchedSource(scope, filename)) return;
                    clearTimeout(timer);
                    timer = setTimeout(() => {
                        timer = undefined;
                        if (!closed) onChange();
                    }, SETTLE_MS);
                },
            );
            watchers.push(watcher);
            watcher.on('error', fail);
        }
    } catch (error) {
        fail(error);
    }

    return close;
}
